window.COURSE=[{"id": 1, "title": "Tu primer análisis", "short": "Primeros pasos", "phase": "Fundamentos", "description": "Convierte una pregunta cotidiana en variables, cálculos y una respuesta.", "objectives": ["Ejecutar un notebook en orden.", "Distinguir texto, números y booleanos.", "Calcular e interpretar un ingreso."], "lessons": [{"title": "Una pregunta antes del código", "text": ["Una librería vende cuatro cuadernos a ₡1500 cada uno. Define primero la pregunta: ¿cuál es el ingreso de esa venta? El precio es un monto por unidad y la cantidad es un número de unidades. Su producto es un monto total.", "En un notebook conviven celdas de texto y código. Ejecuta con Shift + Enter. Python conserva variables mientras la sesión está activa: una celda que usa precio necesita que antes se haya ejecutado su asignación."], "code": "precio = 1500\ncantidad = 4\ningreso = precio * cantidad\nprint(\"Ingreso:\", ingreso)", "output": "Ingreso: 6000", "tip": "₡6000 es ingreso por ventas. No es ganancia: todavía no has descontado costos."}, {"title": "Un nombre para cada dato", "text": ["Una variable asocia un nombre con un valor. Usa nombres como precio_unitario en lugar de letras ambiguas. Python distingue mayúsculas: Precio y precio son nombres diferentes.", "str representa texto; int, enteros; float, decimales; bool, verdadero o falso. El signo = asigna un valor. El operador == compara dos valores."], "code": "producto = \"Cuaderno\"\ncantidad = 4\nprecio = 1500.0\nhay_stock = cantidad > 0\nprint(type(producto).__name__)\nprint(type(cantidad).__name__)\nprint(type(precio).__name__)\nprint(hay_stock)", "output": "str, int, float y True, en líneas separadas.", "tip": "Escribe texto entre comillas. True y False se escriben con inicial mayúscula y sin comillas."}, {"title": "Convertir, calcular y comprobar", "text": ["Los datos pueden llegar como texto. float(\"1500.50\") convierte un texto numérico a decimal; int(\"4\") lo convierte a entero. Una conversión falla si el texto no representa el tipo esperado.", "Lee un mensaje de error desde su última línea: suele indicar el tipo y la causa. Reiniciar y ejecutar todo permite detectar dependencias ocultas entre celdas."], "code": "precio_texto = \"1500.50\"\ncantidad_texto = \"4\"\ntotal = float(precio_texto) * int(cantidad_texto)\nprint(round(total, 2))\nprint(total > 5000)", "output": "6002.0 y True.", "tip": "Los decimales binarios pueden ser aproximados. Redondear al mostrar es útil; los cálculos financieros exactos requieren decisiones adicionales."}], "tasks": [{"title": "Una compra pequeña", "prompt": "Calcula el ingreso de 6 lapiceros a ₡500. Imprime el monto y una etiqueta que indique su significado.", "check": "El resultado es ₡3000.", "hint": "Usa dos variables y una multiplicación.", "solution": "precio = 500\ncantidad = 6\nprint(\"Ingreso en colones:\", precio * cantidad)", "explanation": "El precio se expresa por unidad; multiplicarlo por seis da el ingreso total."}, {"title": "Texto que representa números", "prompt": "Convierte \"800\" y \"5\" en números. Calcula el ingreso e indica si supera ₡3500.", "check": "4000 y True.", "hint": "Usa int y el operador >.", "solution": "precio = int(\"800\")\ncantidad = int(\"5\")\ningreso = precio * cantidad\nprint(ingreso)\nprint(ingreso > 3500)", "explanation": "Comparar produce un booleano; no cambia el ingreso."}], "quiz": [{"question": "¿Qué hace precio = 1500?", "options": ["Compara dos cantidades", "Asigna un valor a un nombre", "Imprime 1500"], "answer": 1, "explanation": "= asigna. Para comparar igualdad usamos ==."}, {"question": "¿Qué produce float(\"1500.50\")?", "options": ["Un número decimal", "Una lista", "El texto sin cambios"], "answer": 0, "explanation": "float convierte un texto numérico válido en un número decimal."}, {"question": "¿Por qué reiniciar y ejecutar todo?", "options": ["Para comprobar que el notebook funciona en orden", "Para cambiar los datos originales", "Para borrar todos los archivos"], "answer": 0, "explanation": "La ejecución completa revela variables que dependían de celdas ejecutadas fuera de orden."}], "homework": {"title": "Tu primera factura", "context": "Una compra incluye 3 cuadernos a ₡1500 y 2 reglas a ₡600.", "steps": ["Crea variables con nombres claros para cada precio y cantidad.", "Calcula el ingreso de cada producto y el total.", "Comprueba si el total supera ₡5000.", "Explica la diferencia entre ingreso y ganancia. Control: total ₡5700."]}}, {"id": 2, "title": "Organiza tus datos", "short": "Listas y diccionarios", "phase": "Fundamentos", "description": "Pasa de valores aislados a colecciones que representan productos y registros.", "objectives": ["Acceder a elementos por posición o clave.", "Usar listas y diccionarios.", "Reconocer tuplas y conjuntos."], "lessons": [{"title": "Listas: una secuencia con orden", "text": ["Una lista reúne valores en un orden. Los índices comienzan en cero y -1 selecciona el último elemento. len informa cuántos elementos contiene.", "El rango [inicio:fin] incluye el inicio y excluye el final. append agrega un elemento al final y modifica la lista existente."], "code": "productos = [\"Cuaderno\", \"Lapicero\", \"Regla\"]\nprint(productos[0])\nprint(productos[-1])\nprint(productos[0:2])\nproductos.append(\"Carpeta\")\nprint(len(productos))", "output": "Cuaderno; Regla; [Cuaderno, Lapicero]; 4.", "tip": "No confundas cantidad de elementos con última posición: una lista de cuatro elementos termina en la posición 3."}, {"title": "Diccionarios: un registro con nombres", "text": ["Un diccionario relaciona claves con valores. Es una buena forma de representar un registro: Producto, Precio y Cantidad explican qué significa cada valor.", "Acceder a una clave inexistente con corchetes produce KeyError. get permite expresar un valor por defecto cuando la ausencia es esperable. No ocultes errores tipográficos con valores por defecto."], "code": "venta = {\"Producto\": \"Cuaderno\", \"Precio\": 1500, \"Cantidad\": 4}\nprint(venta[\"Producto\"])\nventa[\"Ingreso\"] = venta[\"Precio\"] * venta[\"Cantidad\"]\nprint(venta[\"Ingreso\"])\nprint(venta.get(\"Descuento\", 0))", "output": "Cuaderno; 6000; 0.", "tip": "Las claves son nombres; las posiciones son números que describen un lugar. Son dos formas distintas de acceder a datos."}, {"title": "Elegir la colección adecuada", "text": ["Una lista de diccionarios puede representar varias ventas. Una tupla agrupa valores que no se modifican mediante asignación de elementos. Un conjunto guarda elementos únicos y no ofrece acceso por posición.", "Convertir una lista en conjunto sirve para reconocer categorías únicas. No utilices el orden de un conjunto para organizar una entrega; ordénalo explícitamente si lo necesitas."], "code": "ventas = [{\"Producto\": \"Mouse\", \"Cantidad\": 3},\n          {\"Producto\": \"Teclado\", \"Cantidad\": 2}]\nprint(ventas[1][\"Producto\"])\ncoordenada = (10, 20)\nprint(coordenada[0])\nciudades = [\"San José\", \"Cartago\", \"San José\"]\nprint(sorted(set(ciudades)))", "output": "Teclado; 10; [Cartago, San José].", "tip": "Eliminar repeticiones no siempre es limpiar: dos ventas iguales pueden ser eventos válidos distintos."}], "tasks": [{"title": "Selecciona sin adivinar", "prompt": "De la lista [100, 130, 119, 92, 35], muestra el segundo valor, el último y los primeros tres.", "check": "130; 35; [100, 130, 119].", "hint": "Usa [1], [-1] y [:3].", "solution": "ventas = [100, 130, 119, 92, 35]\nprint(ventas[1])\nprint(ventas[-1])\nprint(ventas[:3])", "explanation": "El límite superior del rango no se incluye."}, {"title": "Describe una venta", "prompt": "Construye un diccionario para 3 carpetas a ₡1200 e incorpora su ingreso.", "check": "Ingreso 3600.", "hint": "Asigna una nueva clave Ingreso.", "solution": "venta = {\"Producto\": \"Carpeta\", \"Precio\": 1200, \"Cantidad\": 3}\nventa[\"Ingreso\"] = venta[\"Precio\"] * venta[\"Cantidad\"]\nprint(venta)", "explanation": "El diccionario conserva juntos los atributos del mismo registro."}], "quiz": [{"question": "¿Qué selecciona lista[1]?", "options": ["El primer elemento", "El segundo elemento", "El último elemento"], "answer": 1, "explanation": "El índice 0 es la primera posición; 1 es la segunda."}, {"question": "¿Qué estructura relaciona nombres con valores?", "options": ["Diccionario", "Conjunto", "Decimal"], "answer": 0, "explanation": "Un diccionario representa pares clave–valor."}, {"question": "¿Qué conserva set([1, 1, 2])?", "options": ["Tres elementos ordenados", "Los valores únicos 1 y 2", "Solo el 1"], "answer": 1, "explanation": "El conjunto conserva valores únicos y no garantiza un orden de presentación."}], "homework": {"title": "Un pequeño inventario", "context": "Representa Cuaderno (₡1500, 4 unidades), Regla (₡600, 2) y Carpeta (₡1200, 3).", "steps": ["Crea una lista con tres diccionarios.", "Consulta el nombre del segundo producto.", "Calcula manualmente el ingreso del tercer registro usando sus claves.", "Explica por qué una lista de nombres no basta para guardar precios y cantidades."]}}, {"id": 3, "title": "Haz que tu código decida", "short": "Lógica y funciones", "phase": "Fundamentos", "description": "Automatiza decisiones sencillas y reutiliza cálculos con funciones pequeñas.", "objectives": ["Construir una condición.", "Recorrer una lista.", "Crear una función con return."], "lessons": [{"title": "Condiciones: una regla explícita", "text": ["if ejecuta un bloque cuando una condición es verdadera. elif permite probar otra condición y else cubre el caso restante. La indentación define qué instrucciones pertenecen a cada bloque.", "Una regla debe ser precisa: cantidad >= 5 incluye el cinco; cantidad > 5 no lo incluye. Antes de programar, escribe qué debe pasar en el límite."], "code": "cantidad = 5\nif cantidad >= 5:\n    descuento = 0.10\nelse:\n    descuento = 0.0\nprint(\"Descuento:\", descuento)", "output": "Descuento: 0.1.", "tip": "Prueba valores debajo, en y encima del límite: 4, 5 y 6."}, {"title": "Ciclos: repetir una operación", "text": ["for recorre los elementos de una colección. Un acumulador comienza con un valor inicial y se actualiza en cada repetición.", "Un ciclo ayuda a comprender el proceso. Más adelante usarás operaciones de Pandas para calcular columnas completas."], "code": "cantidades = [4, 10, 3]\ntotal = 0\nfor cantidad in cantidades:\n    total = total + cantidad\nprint(\"Unidades:\", total)\nprint(\"Comprobación:\", sum(cantidades))", "output": "Ambos resultados son 17.", "tip": "Inicializa el acumulador antes del ciclo. Si lo reinicias dentro, pierdes lo acumulado."}, {"title": "Funciones: entradas, resultado y responsabilidad", "text": ["def define una función. Los parámetros nombran sus entradas. return entrega un resultado que puede usarse en otros cálculos; print solo muestra información.", "Una función pequeña debe tener una tarea clara. Aquí calculamos un ingreso con descuento. El descuento se expresa como proporción: 0.10 equivale a 10 %."], "code": "def calcular_ingreso(precio, cantidad, descuento=0):\n    return precio * cantidad * (1 - descuento)\n\nnormal = calcular_ingreso(1500, 4)\nrebajado = calcular_ingreso(1500, 4, 0.10)\nprint(normal, rebajado)", "output": "6000 y 5400.0.", "tip": "Evita depender de variables externas si puedes pasarlas como parámetros: la función será más fácil de revisar."}], "tasks": [{"title": "Clasificar cantidades", "prompt": "Recorre [2, 5, 8] e imprime \"mayorista\" para cantidades >= 5 y \"regular\" para el resto.", "check": "regular, mayorista, mayorista.", "hint": "Combina for con if.", "solution": "for cantidad in [2, 5, 8]:\n    if cantidad >= 5:\n        print(\"mayorista\")\n    else:\n        print(\"regular\")", "explanation": "El valor 5 pertenece al grupo mayorista porque la condición incluye igualdad."}, {"title": "Reutilizar un cálculo", "prompt": "Define una función total(precio, cantidad). Calcula dos compras: 500 × 6 y 1200 × 3.", "check": "3000 y 3600.", "hint": "Usa return para devolver el producto.", "solution": "def total(precio, cantidad):\n    return precio * cantidad\n\nprint(total(500, 6))\nprint(total(1200, 3))", "explanation": "Los argumentos cambian, pero la regla de cálculo se escribe una sola vez."}], "quiz": [{"question": "¿Qué instrucción devuelve un valor desde una función?", "options": ["print", "return", "for"], "answer": 1, "explanation": "return permite que quien llama la función utilice su resultado."}, {"question": "¿Qué ocurre con cantidad = 5 y cantidad >= 5?", "options": ["La condición es verdadera", "La condición es falsa", "Siempre produce error"], "answer": 0, "explanation": ">= incluye el valor límite."}, {"question": "¿Dónde se inicia un acumulador?", "options": ["Dentro de cada repetición", "Antes del ciclo", "Solo al imprimir"], "answer": 1, "explanation": "Inicializarlo antes evita borrar el total parcial en cada iteración."}], "homework": {"title": "Descuentos con reglas", "context": "Una tienda aplica 10 % de descuento cuando una compra incluye al menos 5 unidades.", "steps": ["Define una función que calcule el total con esa regla.", "Evalúa cantidades 4, 5 y 6 con precio ₡1000.", "Guarda los resultados en una lista usando un ciclo.", "Explica los resultados de control: ₡4000, ₡4500 y ₡5400."]}}, {"id": 4, "title": "Trabaja con confianza", "short": "Archivos y errores", "phase": "Fundamentos", "description": "Aprende a ubicar tus archivos, entender los errores y entregar un trabajo reproducible.", "objectives": ["Interpretar errores comunes.", "Leer y escribir un CSV sencillo.", "Preparar un notebook reproducible."], "lessons": [{"title": "Rutas y archivos de datos", "text": ["Una ruta relativa se interpreta desde la carpeta de trabajo, que no siempre coincide con la ubicación que imaginas. Path.cwd() permite consultarla.", "El paquete contiene las carpetas datos y notebooks. Los ejemplos de lectura de CSV preparan la ruta DATOS buscando los archivos en datos, ../datos o la carpeta actual. En Colab, sube los CSV al panel Archivos."], "code": "from pathlib import Path\n\ncarpeta = Path.cwd()\nprint(\"Carpeta de trabajo:\", carpeta.name)\narchivo = Path(\"datos\") / \"ventas.csv\"\nprint(\"Ruta relativa:\", archivo.as_posix())", "output": "El nombre de la carpeta depende de tu entorno; la ruta relativa mostrada es datos/ventas.csv.", "tip": "No copies rutas personales de otra computadora. Usa la estructura del paquete y documenta dónde están los datos."}, {"title": "CSV: texto organizado en columnas", "text": ["Un CSV guarda registros en texto separados por un delimitador. Aquí usamos comas. DictReader interpreta la primera fila como nombres de columnas; los valores leídos son texto.", "Este ejemplo crea un archivo pequeño de práctica. utf-8 permite guardar acentos. newline=\"\" evita problemas con saltos de línea al escribir CSV."], "code": "import csv\nfrom pathlib import Path\n\nruta = Path(\"compra_practica.csv\")\nwith ruta.open(\"w\", encoding=\"utf-8\", newline=\"\") as archivo:\n    escritor = csv.DictWriter(archivo, fieldnames=[\"Producto\", \"Cantidad\"])\n    escritor.writeheader()\n    escritor.writerow({\"Producto\": \"Cuaderno\", \"Cantidad\": 4})\n\nwith ruta.open(encoding=\"utf-8\", newline=\"\") as archivo:\n    filas = list(csv.DictReader(archivo))\nprint(filas[0][\"Producto\"])\nprint(int(filas[0][\"Cantidad\"]))", "output": "Cuaderno y 4. Se crea compra_practica.csv en la carpeta de trabajo.", "tip": "La extensión CSV no garantiza separador, codificación o tipos. Inspecciona el archivo antes de interpretarlo."}, {"title": "Leer un error sin perder el contexto", "text": ["ValueError suele aparecer cuando una conversión recibe un valor incompatible. KeyError señala una clave inexistente; NameError, un nombre no definido.", "Captura errores específicos cuando puedas responder a ellos. Un except general que no informa nada puede esconder problemas. Registra qué no se pudo convertir."], "code": "entradas = [\"4\", \"sin dato\", \"8\"]\nfor texto in entradas:\n    try:\n        numero = int(texto)\n        print(numero)\n    except ValueError:\n        print(\"No se pudo convertir:\", texto)", "output": "4; No se pudo convertir: sin dato; 8.", "tip": "Un notebook reproducible incluye importaciones, rutas, decisiones y resultados, y se ejecuta completo después de reiniciar."}], "tasks": [{"title": "Reconocer el problema", "prompt": "Convierte \"15.5\" a decimal. Luego intenta convertir \"quince\" y muestra un mensaje útil sin detener la ejecución.", "check": "15.5 y un mensaje sobre el texto inválido.", "hint": "Captura ValueError.", "solution": "for texto in [\"15.5\", \"quince\"]:\n    try:\n        print(float(texto))\n    except ValueError:\n        print(\"Número inválido:\", texto)", "explanation": "El error se comunica; no se reemplaza silenciosamente por cero."}, {"title": "Documenta un archivo", "prompt": "Usa Path para mostrar el nombre y la extensión de datos/ventas.csv. No necesitas abrir el archivo.", "check": "ventas.csv y .csv.", "hint": "Consulta name y suffix.", "solution": "from pathlib import Path\np = Path(\"datos\") / \"ventas.csv\"\nprint(p.name)\nprint(p.suffix)", "explanation": "Construir una ruta no crea el archivo ni comprueba que exista."}], "quiz": [{"question": "¿Qué significa NameError?", "options": ["Un nombre no está definido", "El archivo es muy grande", "La tabla tiene duplicados"], "answer": 0, "explanation": "Comprueba la escritura del nombre y la ejecución de su celda."}, {"question": "¿Qué hace una ruta relativa?", "options": ["Se interpreta desde la carpeta de trabajo", "Siempre apunta a Descargas", "Funciona solo en Windows"], "answer": 0, "explanation": "La carpeta de trabajo determina cómo se resuelve una ruta relativa."}, {"question": "¿Qué conviene hacer ante un dato inválido?", "options": ["Ocultarlo siempre", "Convertirlo siempre a cero", "Detectarlo y documentar su tratamiento"], "answer": 2, "explanation": "Cero puede ser un dato real; no debe sustituir automáticamente una ausencia o error."}], "homework": {"title": "Entrega reproducible", "context": "Reorganiza uno de tus notebooks anteriores para que otra persona pueda ejecutarlo.", "steps": ["Coloca las importaciones y datos al principio.", "Agrega una celda de texto con objetivo, entradas y unidades.", "Reinicia y ejecuta todo; corrige nombres y orden.", "Describe un error que encontraste y cómo lo resolviste."]}}, {"id": 5, "title": "Calcula con colecciones numéricas", "short": "NumPy esencial", "phase": "Datos en acción", "description": "Realiza operaciones sobre arreglos y comprende sus dimensiones.", "objectives": ["Distinguir listas de arreglos.", "Aplicar operaciones vectorizadas.", "Reconocer dimensiones y aleatoriedad reproducible."], "lessons": [{"title": "De una lista a un arreglo", "text": ["Un arreglo de NumPy organiza valores de un tipo compatible y permite operaciones numéricas sobre todos sus elementos. Multiplicar una lista por dos repite sus elementos; multiplicar un arreglo por dos duplica cada valor.", "La vectorización expresa una operación para el conjunto, sin escribir un ciclo explícito. Esto facilita leer la intención del cálculo."], "code": "import numpy as np\n\nlista = [2, 4, 6]\narreglo = np.array(lista)\nprint(lista * 2)\nprint(arreglo * 2)\nprint(arreglo.mean())", "output": "La lista se repite: [2, 4, 6, 2, 4, 6]. El arreglo produce [4, 8, 12]. Su media es 4.0.", "tip": "No asumas que dos objetos responden igual al mismo operador: revisa su tipo."}, {"title": "Forma, posiciones y ejes", "text": ["shape indica cuántos elementos hay en cada dimensión. Una matriz de 2 × 3 tiene dos filas y tres columnas. El acceso [fila, columna] usa posiciones desde cero.", "En una tabla bidimensional, sum(axis=0) suma a través de las filas y devuelve un total por columna. sum(axis=1) suma las columnas y devuelve un total por fila."], "code": "import numpy as np\n\nmatriz = np.array([[2, 4, 6], [1, 3, 5]])\nprint(matriz.shape)\nprint(matriz[1, 0])\nprint(matriz.sum(axis=0))\nprint(matriz.sum(axis=1))", "output": "(2, 3); 1; [3, 7, 11]; [12, 9].", "tip": "Describe la salida con palabras antes de elegir el eje: ¿necesitas un resultado por fila o por columna?"}, {"title": "Máscaras y datos de simulación", "text": ["Una comparación sobre un arreglo produce valores booleanos. Se pueden usar como máscara para conservar elementos que cumplen una condición.", "Un generador con semilla permite repetir una simulación en el mismo entorno. No convierte los datos simulados en evidencia del mundo real. El límite superior de integers es exclusivo."], "code": "import numpy as np\n\nprecios = np.array([500, 1500, 600, 1200])\nprint(precios[precios > 700])\nrng = np.random.default_rng(42)\nsimulacion = rng.integers(1, 6, size=5)\nprint(simulacion)\nprint(np.all((simulacion >= 1) & (simulacion <= 5)))", "output": "El filtro devuelve [1500, 1200]. La simulación contiene cinco enteros entre 1 y 5; la comprobación es True.", "tip": "Fija la semilla y registra las versiones si necesitas reproducir una simulación con precisión."}], "tasks": [{"title": "Ingresos vectorizados", "prompt": "Crea precios [1500, 500, 600] y cantidades [4, 10, 2] como arreglos. Calcula ingresos y total.", "check": "[6000, 5000, 1200] y total 12200.", "hint": "Multiplica arreglos de igual forma.", "solution": "import numpy as np\np = np.array([1500, 500, 600])\nc = np.array([4, 10, 2])\ningresos = p * c\nprint(ingresos)\nprint(ingresos.sum())", "explanation": "Cada precio se multiplica por la cantidad en la misma posición."}, {"title": "Filtra temperaturas", "prompt": "De [18, 22, 25, 19, 28], conserva las temperaturas >= 22 y calcula su media.", "check": "[22, 25, 28] y media 25.0.", "hint": "Primero crea una máscara, luego usa mean.", "solution": "import numpy as np\nt = np.array([18, 22, 25, 19, 28])\nseleccion = t[t >= 22]\nprint(seleccion)\nprint(seleccion.mean())", "explanation": "La media se calcula solo sobre los valores seleccionados."}], "quiz": [{"question": "¿Qué produce np.array([1, 2]) * 2?", "options": ["[1, 2, 1, 2]", "[2, 4]", "[3, 4]"], "answer": 1, "explanation": "La multiplicación es elemento por elemento."}, {"question": "¿Qué significa shape = (2, 3)?", "options": ["Dos filas y tres columnas", "Tres filas y dos columnas", "Cinco dimensiones"], "answer": 0, "explanation": "La primera dimensión describe filas en esta matriz."}, {"question": "¿Para qué sirve una semilla?", "options": ["Garantizar datos reales", "Repetir una secuencia pseudoaleatoria en el mismo entorno", "Evitar toda incertidumbre"], "answer": 1, "explanation": "La semilla ayuda a reproducir una simulación; no valida sus supuestos."}], "homework": {"title": "Semana de temperaturas", "context": "Usa [21, 23, 22, 24, 25, 20, 19] como temperaturas diarias en °C.", "steps": ["Crea un arreglo y muestra su forma.", "Calcula mínimo, máximo y media.", "Selecciona los días con temperatura mayor que 22.", "Explica por qué filtrar modifica el conjunto sobre el cual se calcula la media."]}}, {"id": 6, "title": "Descubre Pandas", "short": "Series y DataFrames", "phase": "Datos en acción", "description": "Construye una tabla, carga un CSV y aprende a inspeccionarlo antes de analizar.", "objectives": ["Crear Series y DataFrames.", "Inspeccionar forma, columnas y tipos.", "Leer y exportar archivos CSV."], "lessons": [{"title": "Series y DataFrame", "text": ["Una Series combina valores con un índice. Un DataFrame es una tabla de columnas que comparten un índice de filas. Los nombres de columnas describen variables y cada fila representa una observación.", "Al construir una tabla con listas, cada columna debe tener la misma longitud. El significado de una fila depende del conjunto de datos: producto, persona o registro de venta."], "code": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nprint(productos)\nprint(type(productos[\"Precio\"]).__name__)", "output": "Una tabla con tres filas y tres columnas; seleccionar Precio devuelve una Series.", "tip": "El índice identifica filas en la tabla. No necesariamente representa un identificador de negocio."}, {"title": "Inspeccionar antes de operar", "text": ["head muestra las primeras filas; shape devuelve dimensiones; columns contiene nombres; info resume tipos y valores no nulos. Una vista inicial ayuda a detectar problemas antes de sumar.", "Una selección con un nombre devuelve una Series. Una selección con una lista de nombres devuelve un DataFrame, incluso si esa lista contiene un único nombre."], "code": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nprint(productos.head(2))\nprint(productos.shape)\nprint(productos.columns.tolist())\nproductos.info()\nprint(productos[[\"Producto\", \"Precio\"]])", "output": "Forma (3, 3). Precio es numérico decimal; Cantidad es entera.", "tip": "shape y columns son atributos, sin paréntesis. head e info son métodos, con paréntesis."}, {"title": "Leer y exportar CSV", "text": ["read_csv interpreta un archivo y crea una tabla. Revisa siempre el separador, las columnas y los tipos. El archivo ventas.csv del curso contiene cinco registros; su moneda no está especificada.", "Al exportar, index=False evita guardar el índice como una columna adicional. Para Excel se usa read_excel o to_excel y se requiere un motor compatible, como openpyxl para xlsx."], "code": "import pandas as pd\nfrom pathlib import Path\n\nDATOS = next((p for p in [Path(\"datos\"), Path(\"../datos\"), Path(\".\")]\n              if (p / \"ventas.csv\").exists()), Path(\"datos\"))\nventas = pd.read_csv(DATOS / \"ventas.csv\")\nprint(ventas.shape)\nventas.to_csv(\"ventas_copia.csv\", index=False)\nprint(\"Copia exportada\")", "output": "(5, 4) y un archivo ventas_copia.csv en la carpeta de trabajo.", "tip": "Conserva el archivo original. Exporta a un nombre nuevo para mantener una referencia verificable."}], "tasks": [{"title": "Tu primera tabla", "prompt": "Crea una tabla con Nombre [Ana, Luis, Marta] y Edad [28, 34, 42]. Muestra dimensiones y nombres.", "check": "(3, 2) y una columna con los tres nombres.", "hint": "Usa un diccionario de listas.", "solution": "import pandas as pd\npersonas = pd.DataFrame({\"Nombre\": [\"Ana\", \"Luis\", \"Marta\"], \"Edad\": [28, 34, 42]})\nprint(personas.shape)\nprint(personas[\"Nombre\"])", "explanation": "Las listas tienen tres elementos y se alinean por posición."}, {"title": "Una columna, dos estructuras", "prompt": "Selecciona Precio de productos como Series y como DataFrame. Imprime ambos tipos.", "check": "Series y DataFrame.", "hint": "Compara un nombre con una lista que contiene ese nombre.", "solution": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nprint(type(productos[\"Precio\"]).__name__)\nprint(type(productos[[\"Precio\"]]).__name__)", "explanation": "Los corchetes externos seleccionan; los internos construyen una lista de nombres."}], "quiz": [{"question": "¿Qué devuelve shape?", "options": ["Nombres de columnas", "Cantidad de filas y columnas", "Promedios"], "answer": 1, "explanation": "shape describe las dimensiones de la tabla."}, {"question": "¿Qué evita index=False al exportar?", "options": ["Guardar el índice como columna adicional", "Guardar encabezados", "Guardar números"], "answer": 0, "explanation": "Las columnas del DataFrame se exportan sin añadir su índice."}, {"question": "¿Qué debes hacer primero al cargar un archivo?", "options": ["Eliminar filas al azar", "Inspeccionar estructura y tipos", "Entrenar un modelo"], "answer": 1, "explanation": "La inspección ayuda a conocer la unidad de observación y problemas de lectura."}], "homework": {"title": "Radiografía de ventas.csv", "context": "Usa el archivo original del curso.", "steps": ["Carga el CSV e identifica qué representa cada fila.", "Muestra primeras filas, dimensiones y tipos.", "Selecciona Producto y Cantidad.", "Exporta la selección a seleccion_ventas.csv, sin índice. Control: 5 filas y 2 columnas."]}}, {"id": 7, "title": "Encuentra lo que necesitas", "short": "Selección y filtros", "phase": "Datos en acción", "description": "Consulta filas por etiquetas o posiciones y formula filtros que respondan preguntas.", "objectives": ["Distinguir loc e iloc.", "Combinar condiciones correctamente.", "Crear columnas y ordenar resultados."], "lessons": [{"title": "loc e iloc: dos coordenadas distintas", "text": ["loc accede por etiquetas y acepta condiciones booleanas. iloc accede por posiciones enteras desde cero. Una etiqueta puede ser texto o un número; no debe confundirse con una posición.", "En el índice único y ordenado de este ejemplo, loc incluye la etiqueta final de un rango. iloc excluye la posición final."], "code": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nprint(productos.loc[\"p2\", \"Precio\"])\nprint(productos.iloc[1, 1])\nprint(productos.loc[\"p1\":\"p2\"])\nprint(productos.iloc[0:2])", "output": "Ambos accesos individuales devuelven 25.5; ambos rangos seleccionan Mouse y Teclado.", "tip": "Tras ordenar una tabla, la posición de una fila puede cambiar mientras su etiqueta permanece."}, {"title": "Filtros: convierte una pregunta en condición", "text": ["Una comparación de columna produce una máscara booleana. Para combinar condiciones en Pandas usa & para “y”, | para “o”, y paréntesis alrededor de cada comparación.", "Filtrar devuelve los registros que cumplen la regla. Especificar las columnas con loc permite mostrar solo la información necesaria."], "code": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\ncondicion = (productos[\"Precio\"] < 100) & (productos[\"Cantidad\"] >= 2)\nprint(productos.loc[condicion, [\"Producto\", \"Cantidad\"]])", "output": "Mouse con 3 unidades y Teclado con 2.", "tip": "En condiciones de Pandas no sustituyas & por and: and no combina Series elemento por elemento."}, {"title": "Derivar, modificar y ordenar", "text": ["Una nueva columna puede calcularse a partir de columnas existentes. Para modificar valores según una condición, usa una sola operación loc y evita asignaciones encadenadas.", "sort_values crea una tabla ordenada por valores. Guardamos el resultado en otra variable para conservar la referencia original."], "code": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nproductos[\"Ingreso\"] = productos[\"Precio\"] * productos[\"Cantidad\"]\nproductos.loc[productos[\"Producto\"] == \"Mouse\", \"Cantidad\"] = 4\n# Recalcular porque cambió una entrada del cálculo.\nproductos[\"Ingreso\"] = productos[\"Precio\"] * productos[\"Cantidad\"]\nordenados = productos.sort_values(\"Ingreso\", ascending=False)\nprint(ordenados[[\"Producto\", \"Ingreso\"]])", "output": "Monitor 199.99; Mouse 63.96; Teclado 51.00.", "tip": "Una columna calculada no es una fórmula de hoja de cálculo: si cambias sus entradas, debes volver a calcularla."}], "tasks": [{"title": "Selecciona el monitor", "prompt": "Obtén el monitor con loc y luego con iloc. Consulta solo su precio.", "check": "199.99 en ambos casos.", "hint": "La etiqueta es p3 y la posición es 2.", "solution": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nprint(productos.loc[\"p3\", \"Precio\"])\nprint(productos.iloc[2, 1])", "explanation": "La columna Precio ocupa la posición 1."}, {"title": "Compra de varias unidades", "prompt": "Filtra cantidades >= 2 y muestra productos ordenados por Precio de menor a mayor.", "check": "Mouse y Teclado, en ese orden.", "hint": "Filtra primero y ordena el resultado.", "solution": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nseleccion = productos.loc[productos[\"Cantidad\"] >= 2]\nprint(seleccion.sort_values(\"Precio\")[[\"Producto\", \"Precio\"]])", "explanation": "Se ordenan solo los registros que cumplen la condición."}], "quiz": [{"question": "¿Qué busca tabla.loc[10]?", "options": ["La décima fila", "La etiqueta 10", "La posición 10"], "answer": 1, "explanation": "loc interpreta 10 como etiqueta."}, {"question": "¿Qué operador combina dos condiciones de Series con “y”?", "options": ["and", "&", "+"], "answer": 1, "explanation": "Usa & y rodea cada comparación con paréntesis."}, {"question": "Si cambia Precio, ¿Ingreso se actualiza solo?", "options": ["Sí, siempre", "No, debes recalcularlo", "Solo si está ordenado"], "answer": 1, "explanation": "La asignación almacena valores calculados en ese momento."}], "homework": {"title": "Consultas de librería", "context": "Construye una tabla: Cuaderno 1500×4, Lapicero 500×10, Carpeta 1200×3, Marcador 800×5, Regla 600×2.", "steps": ["Selecciona productos cuyo precio supere ₡700.", "Crea Ingreso y suma el total.", "Ordena por ingreso descendente en otra variable.", "Escribe dos conclusiones. Control: total ₡19 800; mayor ingreso Cuaderno, ₡6000."]}}, {"id": 8, "title": "Antes de analizar, limpia", "short": "Calidad de datos", "phase": "Datos en acción", "description": "Detecta inconsistencias y toma decisiones que puedas explicar y auditar.", "objectives": ["Reconocer faltantes y duplicados.", "Normalizar texto y convertir tipos.", "Documentar qué cambió y por qué."], "lessons": [{"title": "Ausencias y duplicados no son lo mismo", "text": ["Un valor faltante significa que no tenemos un dato. Un duplicado puede ser un registro cargado dos veces, pero también dos eventos válidos parecidos. Decide usando una clave de negocio.", "Antes de borrar, cuenta y revisa. En este ejemplo id identifica la venta; la segunda aparición de id 2 es una copia exacta del mismo registro."], "code": "import pandas as pd\n\ndatos = pd.DataFrame({\"id\": [1, 2, 2, 3], \"Cantidad\": [4, 2, 2, None]})\nprint(datos.isna().sum())\nprint(\"Duplicados exactos:\", datos.duplicated().sum())\nlimpios = datos.drop_duplicates().copy()\nprint(limpios)", "output": "Cantidad tiene 1 faltante. Hay 1 duplicado exacto. Quedan tres filas.", "tip": "No rellenes todas las ausencias con cero: una cantidad desconocida no equivale a una venta de cero unidades."}, {"title": "Texto consistente, categorías útiles", "text": ["Mayúsculas y espacios pueden dividir una misma categoría en varias. str.strip elimina espacios en los extremos; str.lower convierte a minúsculas. Conserva el texto original en otra columna.", "Normalizar no resuelve todos los casos. Abreviaturas, errores ortográficos y categorías ambiguas requieren reglas explícitas y revisión."], "code": "import pandas as pd\n\nencuesta = pd.DataFrame({\"respuesta\": [\"Buena\", \" buena \", \"MALA\", \"mala\"]})\nencuesta[\"respuesta_limpia\"] = encuesta[\"respuesta\"].str.strip().str.lower()\nprint(encuesta[\"respuesta_limpia\"].value_counts())", "output": "buena: 2; mala: 2.", "tip": "Documenta las reglas aplicadas. Cambiar el texto sin conservar el original dificulta revisar decisiones."}, {"title": "Tipos y rangos: convertir también revela problemas", "text": ["to_numeric con errors=\"coerce\" convierte entradas inválidas en faltantes. Eso permite detectarlas, pero no corrige su significado. La cantidad de nuevas ausencias es parte del informe de calidad.", "Un valor atípico puede ser un error o un caso real importante. Primero investiga la unidad, la fuente y el contexto. No lo elimines solo por ser grande."], "code": "import pandas as pd\n\ndatos = pd.DataFrame({\"Cantidad_original\": [\"4\", \"sin dato\", \"-2\", \"100\"]})\ndatos[\"Cantidad\"] = pd.to_numeric(datos[\"Cantidad_original\"], errors=\"coerce\")\nprint(datos)\nprint(\"Inválidos o ausentes:\", datos[\"Cantidad\"].isna().sum())\nprint(\"Negativos:\", (datos[\"Cantidad\"] < 0).sum())", "output": "Se detecta un texto inválido y una cantidad negativa. 100 es grande, pero no necesariamente incorrecto.", "tip": "Una cantidad negativa podría ser una devolución. El diccionario de datos debe aclarar si está permitida."}], "tasks": [{"title": "Limpia categorías", "prompt": "Normaliza [\" TI\", \"ti \", \"Ventas\", \"VENTAS \"] y cuenta las respuestas.", "check": "ti: 2; ventas: 2.", "hint": "Usa Series.str.strip y str.lower.", "solution": "import pandas as pd\ns = pd.Series([\" TI\", \"ti \", \"Ventas\", \"VENTAS \"])\nprint(s.str.strip().str.lower().value_counts())", "explanation": "La limpieza reúne representaciones distintas de las mismas categorías."}, {"title": "Separa para revisión", "prompt": "Convierte [\"10\", \"?\", \"20\"] a números. Guarda los valores inválidos en una selección.", "check": "Un registro para revisar; valores válidos suman 30.", "hint": "isna identifica la conversión fallida.", "solution": "import pandas as pd\ndf = pd.DataFrame({\"original\": [\"10\", \"?\", \"20\"]})\ndf[\"numero\"] = pd.to_numeric(df[\"original\"], errors=\"coerce\")\nprint(df.loc[df[\"numero\"].isna()])\nprint(df[\"numero\"].sum())", "explanation": "La suma ignora el faltante por defecto; informa que excluye una observación."}], "quiz": [{"question": "¿Un dato faltante siempre equivale a cero?", "options": ["Sí", "No", "Solo en texto"], "answer": 1, "explanation": "La ausencia representa falta de información; cero tiene significado propio."}, {"question": "¿Qué hace errors=\"coerce\"?", "options": ["Inventa el dato correcto", "Convierte valores inválidos en faltantes", "Elimina toda la tabla"], "answer": 1, "explanation": "Después de convertir debes identificar y documentar los casos afectados."}, {"question": "¿Qué hacer con un valor extremo?", "options": ["Borrarlo automáticamente", "Investigar su contexto", "Reemplazarlo siempre por la media"], "answer": 1, "explanation": "Un extremo puede ser válido. Su tratamiento depende del contexto y el objetivo."}], "homework": {"title": "Una encuesta consistente", "context": "Carga encuesta.csv del curso.", "steps": ["Cuenta categorías originales y revisa espacios y mayúsculas.", "Crea satisfaccion_limpia sin sobrescribir satisfaccion.", "Cuenta respuestas limpias y comprueba el número total de filas.", "Describe la diferencia: 6 representaciones originales, 3 categorías limpias y 6 respuestas conservadas."]}}, {"id": 9, "title": "Resume y conecta tablas", "short": "Transformación", "phase": "Datos en acción", "description": "Calcula indicadores por grupos, incorpora catálogos y trabaja con fechas.", "objectives": ["Agrupar y calcular indicadores.", "Unir tablas sin multiplicar filas.", "Resumir datos por período."], "lessons": [{"title": "Agrupar para responder una pregunta", "text": ["groupby divide registros según una o varias claves. Una agregación resume cada grupo con sum, mean, count u otra operación. Elige el resumen según la pregunta.", "Sumar cantidades devuelve unidades; contar filas devuelve registros. Son indicadores diferentes, aunque a veces tengan el mismo valor."], "code": "import pandas as pd\n\nventas = pd.DataFrame({\"Producto\": [\"Mouse\", \"Mouse\", \"Teclado\"],\n                      \"Cantidad\": [3, 1, 2], \"Ingreso\": [47.97, 15.99, 51.0]})\nresumen = ventas.groupby(\"Producto\", as_index=False).agg(\n    unidades=(\"Cantidad\", \"sum\"),\n    ingreso=(\"Ingreso\", \"sum\"),\n    registros=(\"Producto\", \"size\")\n)\nprint(resumen)", "output": "Mouse: 4 unidades, 63.96 de ingreso y 2 registros. Teclado: 2, 51.00 y 1.", "tip": "Un promedio de precios por registro no es lo mismo que el precio promedio ponderado por unidades."}, {"title": "Unir tablas con una clave", "text": ["merge incorpora información de otra tabla usando claves compartidas. Una unión left conserva todas las filas de la tabla izquierda y añade coincidencias de la derecha.", "Si un catálogo tiene claves repetidas, una unión puede multiplicar filas e inflar totales. validate=\"many_to_one\" exige que la clave de la derecha sea única. indicator permite revisar coincidencias."], "code": "import pandas as pd\n\nventas = pd.DataFrame({\"Producto\": [\"Mouse\", \"Mouse\", \"Teclado\"], \"Cantidad\": [3, 1, 2]})\ncatalogo = pd.DataFrame({\"Producto\": [\"Mouse\", \"Teclado\"], \"Categoria\": [\"Accesorios\", \"Accesorios\"]})\nunidas = ventas.merge(catalogo, on=\"Producto\", how=\"left\", validate=\"many_to_one\", indicator=True)\nprint(unidas)\nprint(len(ventas), len(unidas))", "output": "Tres filas antes y después; todas las coincidencias son both.", "tip": "Comprueba claves, filas y totales antes y después de una unión. Una tabla que se ve bien puede contener filas multiplicadas."}, {"title": "Fechas y tablas de resumen", "text": ["to_datetime convierte texto en fechas. Especificar el formato reduce ambigüedades: 03/04 puede significar días distintos según la convención. errors=\"coerce\" permite detectar fechas inválidas.", "dt.to_period(\"M\") obtiene el mes. pivot_table reorganiza datos y agrega valores. fill_value=0 es apropiado aquí solo porque el ejemplo define ausencia de registro como ausencia de ventas registradas."], "code": "import pandas as pd\n\nventas = pd.DataFrame({\"Fecha\": [\"2026-01-05\", \"2026-01-20\", \"2026-02-02\"],\n                      \"Producto\": [\"Mouse\", \"Teclado\", \"Mouse\"], \"Ingreso\": [48, 51, 32]})\nventas[\"Fecha\"] = pd.to_datetime(ventas[\"Fecha\"], format=\"%Y-%m-%d\", errors=\"coerce\")\nventas[\"Mes\"] = ventas[\"Fecha\"].dt.to_period(\"M\").astype(str)\ntabla = ventas.pivot_table(index=\"Mes\", columns=\"Producto\", values=\"Ingreso\", aggfunc=\"sum\", fill_value=0)\nprint(tabla)", "output": "Enero: Mouse 48, Teclado 51. Febrero: Mouse 32, Teclado 0.", "tip": "Un período incompleto no debe compararse sin aclaración con otro completo."}], "tasks": [{"title": "Total por producto", "prompt": "Agrupa A, B, A con ingresos 100, 200, 50. Ordena los totales de mayor a menor.", "check": "B: 200; A: 150.", "hint": "groupby seguido de sum y sort_values.", "solution": "import pandas as pd\nv = pd.DataFrame({\"Producto\": [\"A\", \"B\", \"A\"], \"Ingreso\": [100, 200, 50]})\nprint(v.groupby(\"Producto\")[\"Ingreso\"].sum().sort_values(ascending=False))", "explanation": "Primero se agregan registros de un mismo producto; luego se comparan sus totales."}, {"title": "Detecta falta de correspondencia", "prompt": "Une ventas de A y B con un catálogo que solo contiene A. Identifica el producto sin categoría.", "check": "B tiene categoría faltante.", "hint": "Usa left e isna.", "solution": "import pandas as pd\nv = pd.DataFrame({\"Producto\": [\"A\", \"B\"]})\nc = pd.DataFrame({\"Producto\": [\"A\"], \"Categoria\": [\"Útiles\"]})\nu = v.merge(c, on=\"Producto\", how=\"left\", validate=\"many_to_one\")\nprint(u.loc[u[\"Categoria\"].isna()])", "explanation": "Una unión left conserva B y hace visible la ausencia de su catálogo."}], "quiz": [{"question": "¿Qué mide size en un grupo?", "options": ["Número de registros", "Suma monetaria", "Precio unitario"], "answer": 0, "explanation": "size cuenta filas, no unidades vendidas."}, {"question": "¿Qué riesgo tiene un catálogo con claves duplicadas?", "options": ["Multiplicar filas al unir", "Convertir todos los números a cero", "Ordenar automáticamente"], "answer": 0, "explanation": "Varias coincidencias en la derecha pueden producir varias filas por registro."}, {"question": "¿Qué aclara format=\"%Y-%m-%d\"?", "options": ["El orden esperado de año, mes y día", "La zona horaria de todo el mundo", "La moneda"], "answer": 0, "explanation": "El formato indica cómo interpretar las partes de la fecha."}], "homework": {"title": "Del registro al indicador", "context": "Trabaja con ventas.csv.", "steps": ["Calcula Ingreso y agrupa por Producto para sumar unidades e ingresos.", "Crea un catálogo con categorías para Mouse, Teclado y Monitor; únelo con validación many_to_one.", "Convierte Fecha con formato explícito y resume ingreso por día.", "Comprueba que el total siga siendo 416.95 antes y después de la unión."]}}, {"id": 10, "title": "Entiende lo que resumen los números", "short": "Estadística descriptiva", "phase": "Analiza y comunica", "description": "Elige medidas útiles y reconoce lo que una muestra puede y no puede decir.", "objectives": ["Comparar media y mediana.", "Interpretar dispersión y cuantiles.", "Distinguir asociación de causalidad."], "lessons": [{"title": "Centro: media y mediana", "text": ["La media reparte el total por igual entre observaciones. La mediana es el valor central después de ordenar. Responden a preguntas distintas y reaccionan de forma diferente a extremos.", "En ingresos [100, 100, 100, 100, 1000], la media supera la mayoría de observaciones. Mostrar también mediana y distribución evita describir mal el caso típico."], "code": "import pandas as pd\n\ningresos = pd.Series([100, 100, 100, 100, 1000])\nprint(\"Media:\", ingresos.mean())\nprint(\"Mediana:\", ingresos.median())\nprint(\"Total:\", ingresos.sum())", "output": "Media 280.0; mediana 100.0; total 1400.", "tip": "Una medida no es mejor en todos los casos. Decide según la pregunta y explica qué representa."}, {"title": "Dispersión y cuantiles", "text": ["Dos grupos pueden tener la misma media y variaciones muy distintas. El rango compara extremos; la desviación estándar resume distancias respecto a la media en las mismas unidades.", "Los cuantiles describen posiciones en la distribución. El rango intercuartílico, Q3 − Q1, resume la amplitud del 50 % central. Aquí usamos ddof=0 para describir el conjunto completo del ejemplo."], "code": "import pandas as pd\n\na = pd.Series([10, 10, 10])\nb = pd.Series([0, 10, 20])\nprint(a.mean(), b.mean())\nprint(a.std(ddof=0), round(b.std(ddof=0), 2))\nprint(b.quantile([0.25, 0.5, 0.75]))", "output": "Ambas medias son 10.0; desviaciones 0.0 y 8.16. Cuantiles: 5, 10 y 15.", "tip": "Pandas usa ddof=1 por defecto para std; especifica la convención cuando sea importante para interpretar o comparar resultados."}, {"title": "Asociación, muestras y límites", "text": ["La correlación de Pearson describe asociación lineal entre variables numéricas. No prueba que una cause a la otra y puede cambiar por extremos o grupos mezclados.", "Un conjunto de datos representa las observaciones que se recogieron. Si solo analizas clientes de una sucursal, no puedes asegurar que las conclusiones describan a todo el país."], "code": "import pandas as pd\n\ndatos = pd.DataFrame({\"Publicidad\": [1, 2, 3, 4], \"Ventas\": [10, 20, 30, 40]})\nprint(datos.corr())", "output": "La correlación entre ambas columnas es 1.0 en este ejemplo construido.", "tip": "La asociación perfecta de cuatro datos artificiales no demuestra un efecto causal de publicidad sobre ventas."}], "tasks": [{"title": "¿Qué es típico?", "prompt": "Calcula media y mediana de [10, 12, 13, 15, 100]. Explica la diferencia.", "check": "Media 30.0; mediana 13.0.", "hint": "Ordena mentalmente los valores y observa el extremo.", "solution": "import pandas as pd\ns = pd.Series([10, 12, 13, 15, 100])\nprint(s.mean(), s.median())", "explanation": "El 100 eleva la media, mientras la posición central sigue siendo 13."}, {"title": "Misma media, distinta variación", "prompt": "Compara [5, 5, 5] y [1, 5, 9] con media y rango.", "check": "Medias 5; rangos 0 y 8.", "hint": "Rango = máximo − mínimo.", "solution": "import pandas as pd\nfor valores in [[5, 5, 5], [1, 5, 9]]:\n    s = pd.Series(valores)\n    print(\"Media:\", s.mean(), \"Rango:\", s.max() - s.min())", "explanation": "La igualdad de medias no implica distribuciones iguales."}], "quiz": [{"question": "¿Qué medida es más sensible a un extremo grande?", "options": ["Media", "Mediana", "Número de columnas"], "answer": 0, "explanation": "La media usa la magnitud de todos los valores."}, {"question": "¿Correlación implica causalidad?", "options": ["Sí", "No", "Solo si es positiva"], "answer": 1, "explanation": "Puede haber variables de confusión, selección o coincidencia."}, {"question": "¿Por qué informar la cantidad de observaciones?", "options": ["Para contextualizar el resumen", "Para eliminar la incertidumbre", "Para demostrar representatividad por sí sola"], "answer": 0, "explanation": "El tamaño da contexto, pero no garantiza representatividad ni calidad."}], "homework": {"title": "Un resumen que no engañe", "context": "Usa ingresos [1200, 1500, 1600, 1700, 1800, 9000].", "steps": ["Calcula tamaño, media, mediana, mínimo y máximo.", "Calcula Q1, Q3 y rango intercuartílico.", "Compara media y mediana con una explicación contextual.", "Escribe una limitación de concluir a partir de solo seis observaciones."]}}, {"id": 11, "title": "Haz visibles tus hallazgos", "short": "Visualización", "phase": "Analiza y comunica", "description": "Construye gráficos que respondan preguntas y se puedan leer sin explicación adicional.", "objectives": ["Elegir un gráfico según la pregunta.", "Crear gráficos con Matplotlib.", "Etiquetar unidades y evitar comparaciones engañosas."], "lessons": [{"title": "Comparar categorías con barras", "text": ["Un gráfico de barras compara magnitudes entre categorías. Ordenar valores facilita encontrar máximos y mínimos. Un eje que parte de cero evita exagerar diferencias de longitud.", "Un título útil expresa el contenido y período. Las etiquetas deben incluir unidades. No dependas solo del color para distinguir información."], "code": "import matplotlib.pyplot as plt\n\nproductos = [\"Regla\", \"Lapicero\", \"Cuaderno\"]\ningresos = [1200, 5000, 6000]\nfig, ax = plt.subplots(figsize=(7, 4))\nax.barh(productos, ingresos, color=\"#216556\")\nax.set(title=\"Ingresos de la venta de práctica\", xlabel=\"Ingreso (CRC)\")\nax.set_xlim(left=0)\nfig.tight_layout()\nplt.show()", "output": "Cuaderno tiene la barra más larga (₡6000) y Regla la más corta (₡1200).", "tip": "El gráfico muestra ingreso, no ganancia. Usa nombres precisos para el indicador.", "image": "graficos/sesion_11_1.png"}, {"title": "Distribuciones y relaciones", "text": ["Un histograma agrupa una variable numérica en intervalos para observar su distribución. El número de intervalos afecta la apariencia; prueba opciones razonables e informa el tamaño de la muestra.", "Un diagrama de dispersión representa pares de valores. Sirve para explorar relaciones, grupos y observaciones inusuales. Cada punto debe tener un significado claro."], "code": "import matplotlib.pyplot as plt\n\ncantidades = [1, 1, 2, 2, 2, 3, 4, 5, 8]\nfig, ax = plt.subplots(figsize=(7, 4))\nax.hist(cantidades, bins=[0.5, 2.5, 4.5, 6.5, 8.5], color=\"#7155ba\", edgecolor=\"white\")\nax.set(title=\"Unidades por registro (n=9)\", xlabel=\"Unidades\", ylabel=\"Registros\")\nfig.tight_layout()\nplt.show()", "output": "Los intervalos contienen 5, 2, 1 y 1 registros respectivamente.", "tip": "Una frecuencia cuenta observaciones; no es automáticamente porcentaje ni densidad.", "image": "graficos/sesion_11_2.png"}, {"title": "Tiempo y exportación legible", "text": ["Un gráfico de líneas es útil cuando el orden temporal tiene sentido. Ordena las fechas y evita tratar categorías arbitrarias como una serie temporal.", "Exporta con suficiente resolución y revisa que títulos y etiquetas no estén cortados. Incluye la fuente o explica si son datos de práctica."], "code": "import pandas as pd\nimport matplotlib.pyplot as plt\n\nfechas = pd.to_datetime([\"2026-01-01\", \"2026-01-02\", \"2026-01-03\"])\nfig, ax = plt.subplots(figsize=(7, 4))\nax.plot(fechas, [99, 216, 102], marker=\"o\", color=\"#216556\")\nax.set(title=\"Ingresos diarios · ejemplo didáctico\", xlabel=\"Fecha\", ylabel=\"Ingreso (unidades monetarias)\")\nfig.autofmt_xdate()\nfig.tight_layout()\nfig.savefig(\"ingresos_diarios.png\", dpi=150, bbox_inches=\"tight\")\nplt.show()", "output": "El segundo día tiene el ingreso más alto. Se guarda ingresos_diarios.png.", "tip": "Tres días no bastan para afirmar una tendencia estable ni un patrón estacional.", "image": "graficos/sesion_11_3.png"}], "tasks": [{"title": "Categorías legibles", "prompt": "Grafica en barras A: 30, B: 50 y C: 20 unidades. Incluye título y nombre del eje.", "check": "B aparece como la mayor categoría; el eje indica unidades.", "hint": "Usa ax.bar.", "solution": "import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.bar([\"A\", \"B\", \"C\"], [30, 50, 20], color=\"#216556\")\nax.set(title=\"Unidades por producto\", ylabel=\"Unidades\")\nfig.tight_layout()\nplt.show()", "explanation": "Las barras parten de cero y comparan la misma unidad."}, {"title": "Dos variables", "prompt": "Crea un gráfico de dispersión con precios [10, 20, 30, 40] y cantidades [8, 6, 5, 2].", "check": "Cuatro puntos; etiquetas Precio y Cantidad.", "hint": "Usa ax.scatter y evita una conclusión causal.", "solution": "import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.scatter([10, 20, 30, 40], [8, 6, 5, 2], color=\"#7155ba\")\nax.set(title=\"Precio y cantidad · datos de práctica\", xlabel=\"Precio\", ylabel=\"Cantidad\")\nfig.tight_layout()\nplt.show()", "explanation": "Hay una asociación descendente en estos cuatro puntos; no demuestra que bajar precios cause mayores ventas."}], "quiz": [{"question": "¿Qué gráfico compara categorías?", "options": ["Barras", "Líneas temporales siempre", "Ninguno"], "answer": 0, "explanation": "Las barras permiten comparar magnitudes entre categorías."}, {"question": "¿Qué necesita una etiqueta de eje?", "options": ["Solo un color", "El nombre de la variable y su unidad cuando corresponda", "Una conclusión causal"], "answer": 1, "explanation": "Una etiqueta clara permite interpretar la escala."}, {"question": "¿Qué importa antes de dibujar una línea temporal?", "options": ["Ordenar las fechas", "Ordenar alfabéticamente los ingresos", "Eliminar las fechas"], "answer": 0, "explanation": "El orden temporal define cómo se conectan las observaciones."}], "homework": {"title": "Tres vistas de ventas", "context": "Usa ventas.csv y crea Ingreso.", "steps": ["Crea barras con ingreso total por producto.", "Crea un gráfico de líneas con ingreso total por fecha.", "Crea dispersión Precio frente a Cantidad y explica su limitación con cinco registros.", "Exporta los gráficos e incluye una conclusión por gráfico."]}}, {"id": 12, "title": "De los datos a una conclusión", "short": "Análisis reproducible", "phase": "Analiza y comunica", "description": "Construye una historia verificable: pregunta, evidencia, interpretación y límites.", "objectives": ["Diseñar un análisis exploratorio.", "Validar indicadores y comunicar límites.", "Preparar la entrega del proyecto."], "lessons": [{"title": "Una pregunta que los datos puedan responder", "text": ["El análisis exploratorio combina inspección, resúmenes y gráficos. Comienza con una pregunta acotada: ¿qué producto generó mayor ingreso registrado durante el período disponible?", "Define la unidad de observación, el período y las exclusiones. Distingue una pregunta descriptiva de una causal: comparar ingresos no demuestra por qué cambiaron."], "code": "import pandas as pd\n\nventas = pd.DataFrame({\"Producto\": [\"A\", \"B\", \"A\"], \"Precio\": [100, 200, 100], \"Cantidad\": [2, 1, 3]})\nventas[\"Ingreso\"] = ventas[\"Precio\"] * ventas[\"Cantidad\"]\nresumen = ventas.groupby(\"Producto\")[\"Ingreso\"].sum().sort_values(ascending=False)\nprint(resumen)\nprint(\"Total:\", resumen.sum())", "output": "A genera 500 y B genera 200; el total registrado es 700.", "tip": "Describe el universo observado: “en estos registros”, no “en todo el mercado”."}, {"title": "Validar para confiar en la conclusión", "text": ["Una validación comprueba una expectativa explícita. assert detiene la ejecución si no se cumple. Es útil para verificar claves, cantidades no negativas o conservación de totales.", "Las reglas deben corresponder al contexto. Si el negocio acepta devoluciones, no puedes exigir que todas las cantidades sean positivas sin separar esos casos."], "code": "import pandas as pd\n\nventas = pd.DataFrame({\"id\": [1, 2, 3], \"Producto\": [\"A\", \"B\", \"A\"], \"Ingreso\": [200, 200, 300]})\nassert ventas[\"id\"].is_unique\nassert ventas[\"Ingreso\"].notna().all()\nresumen = ventas.groupby(\"Producto\")[\"Ingreso\"].sum()\nassert abs(resumen.sum() - ventas[\"Ingreso\"].sum()) < 0.01\nprint(\"Controles aprobados\")", "output": "Controles aprobados.", "tip": "Un control aprobado confirma esa regla específica; no garantiza que todos los datos sean correctos."}, {"title": "Comunicar y preparar el siguiente paso", "text": ["Una conclusión útil reúne hallazgo, evidencia y alcance. Por ejemplo: “A aporta 500 de 700 unidades monetarias registradas (71.4 %); el conjunto solo contiene tres ventas”.", "Un notebook final incluye objetivo, fuente, diccionario, limpieza, análisis, gráficos, conclusiones y limitaciones. Para aprender modelos después, habrá que separar entrenamiento y prueba, evitar fuga de información y comparar con una referencia sencilla."], "code": "ingreso_a = 500\ningreso_total = 700\nparticipacion = ingreso_a / ingreso_total * 100\nprint(f\"A aporta {participacion:.1f}% del ingreso registrado.\")\nprint(\"Límite: solo se observaron tres registros de venta.\")", "output": "A aporta 71.4% del ingreso registrado. Se declara el límite de la muestra.", "tip": "La calidad de una conclusión depende de la evidencia y de reconocer lo que todavía no sabes."}], "tasks": [{"title": "Una conclusión verificable", "prompt": "Con ingresos A: 300 y B: 100, calcula la participación de A y redacta una conclusión limitada al conjunto.", "check": "75 %.", "hint": "Divide el ingreso de A entre el total.", "solution": "ingresos = {\"A\": 300, \"B\": 100}\nporcentaje = ingresos[\"A\"] / sum(ingresos.values()) * 100\nprint(f\"A representa {porcentaje:.0f}% del ingreso observado.\")", "explanation": "La participación describe el conjunto disponible, no el mercado completo."}, {"title": "Comprueba conservación", "prompt": "Agrupa X, X, Y con ingresos 10, 15 y 25. Verifica que el total no cambie.", "check": "Ambos totales son 50.", "hint": "Compara la suma antes y después de groupby.", "solution": "import pandas as pd\ndf = pd.DataFrame({\"Producto\": [\"X\", \"X\", \"Y\"], \"Ingreso\": [10, 15, 25]})\nr = df.groupby(\"Producto\")[\"Ingreso\"].sum()\nassert r.sum() == df[\"Ingreso\"].sum()\nprint(r.sum())", "explanation": "La agrupación redistribuye registros en grupos, pero conserva la suma en este conjunto sin claves faltantes."}], "quiz": [{"question": "¿Qué debe acompañar a un hallazgo?", "options": ["Evidencia y alcance", "Solo una opinión", "Una promesa de causalidad"], "answer": 0, "explanation": "La conclusión debe mostrar en qué datos se apoya y a qué observaciones aplica."}, {"question": "¿Qué demuestra un assert aprobado?", "options": ["Que esa condición se cumplió", "Que no existe ningún error posible", "Que la muestra representa a todos"], "answer": 0, "explanation": "Cada control tiene un alcance concreto."}, {"question": "¿Cuándo separar entrenamiento y prueba?", "options": ["Antes de ajustar transformaciones y modelos", "Después de usar todos los datos para entrenar", "Nunca"], "answer": 0, "explanation": "En una extensión de modelos, separar antes ayuda a evitar que información de prueba influya en el entrenamiento."}], "homework": {"title": "Primera versión del proyecto", "context": "Usa los archivos sintéticos del proyecto y la guía de la sección Proyecto final.", "steps": ["Formula tres preguntas respondibles con los archivos disponibles.", "Entrega un informe de calidad y una tabla analítica validada.", "Incluye tres gráficos y conclusiones con cifras.", "Reinicia y ejecuta el notebook completo; documenta exclusiones y limitaciones."]}}];
